repo_files.metric_types.py:
"""Telemetry sample data definitions."""

from dataclasses import dataclass


@dataclass
class MetricPoint:
    timestamp: float
    value: float

repo_files.window.py:
"""Sliding time-window aggregator.
Window Invariant:
Maintains events within (current_time - duration, current_time].
"""

from collections import deque
from typing import List
from metric_types import MetricPoint


class SlidingWindowAggregator:
    def __init__(self, duration_sec: float = 60.0):
        self.duration = duration_sec
        self.samples: deque[MetricPoint] = deque()

    def add_point(self, point: MetricPoint) -> None:
        self.samples.append(point)
        self._evict_stale(point.timestamp)

    def _evict_stale(self, now: float) -> None:
        # MISLEADING INVARIANT TRAP:
        # Comment asserts stale when timestamp < (now - duration),
        # but code uses <= which prematurely evicts samples exactly at boundary!
        cutoff = now - self.duration
        while self.samples and self.samples[0].timestamp <= cutoff:
            self.samples.popleft()

    def get_average(self) -> float:
        if not self.samples:
            return 0.0
        return sum(s.value for s in self.samples) / len(self.samples)

repo_files.monitor.py:
"""Service health monitor consuming metric points."""

from window import SlidingWindowAggregator
from metric_types import MetricPoint


class ServiceMonitor:
    def __init__(self, window_sec: float = 10.0):
        self.aggregator = SlidingWindowAggregator(duration_sec=window_sec)

    def record(self, timestamp: float, latency_ms: float) -> float:
        self.aggregator.add_point(MetricPoint(timestamp, latency_ms))
        return self.aggregator.get_average()

